  "routes.wait_for_acceptance_and_the_time_window_do_not_arrive_unannounced": ["Bitte Zusage und Zeitfenster abwarten. Komm nicht unangekündigt und nimm nur deine vereinbarte Portion.", "Wait for acceptance and the time window. Do not arrive unannounced and take only your agreed portion.", "Onayı ve zaman aralığını bekle. Habersiz gelme ve yalnızca kararlaştırılan porsiyonunu al.", "انتظر الموافقة والموعد. لا تأتِ دون إشعار وخذ حصتك المتفق عليها فقط.", "Pričekaj potvrdu i termin. Ne dolazi nenajavljeno i uzmi samo dogovorenu porciju.", "Attendi conferma e fascia oraria. Non venire senza avvisare e prendi solo la porzione concordata.", "Warte auf die Zusage. Komm zur vereinbarten Zeit. Nimm nur die Portion, die ihr vereinbart habt."],
  "routes.accept_collection": ["Abholung zusagen", "Accept collection", "Teslim almayı onayla", "وافق على الاستلام", "Potvrdi preuzimanje", "Conferma ritiro", "Abholung zusagen"],
  "routes.held_pending_acceptance_until_value_the_portion_becomes_available": ["Für die Zusage vorgemerkt bis {p1}. Danach wird die Portion automatisch wieder frei.", "Held pending acceptance until {p1}. The portion becomes available automatically afterwards.", "{p1} saatine kadar onay için ayrıldı. Ardından porsiyon otomatik olarak yeniden boşalır.", "محجوزة بانتظار الموافقة حتى {p1}. بعدها تصبح الحصة متاحة تلقائيًا.", "Čuva se do potvrde do {p1}. Nakon toga porcija automatski ponovno postaje dostupna.", "Riservata in attesa di conferma fino a {p1}. Dopo la porzione torna automaticamente disponibile.", "Für die Zusage vorgemerkt bis {p1}. Danach wird die Portion automatisch wieder frei."],
  "routes.check_the_agreed_portion_and_scan_the_personal_collection_code_at": ["Prüfe die vereinbarte Portion und scanne bei der Übergabe den persönlichen Abholcode.", "Check the agreed portion and scan the personal collection code at handoff.", "Kararlaştırılan porsiyonu kontrol et ve teslimde kişisel teslim alma kodunu tara.", "تحقق من الحصة وامسح رمز الاستلام الشخصي عند التسليم.", "Provjeri dogovorenu porciju i pri primopredaji skeniraj osobni kod preuzimanja.", "Controlla la porzione concordata e scansiona il codice personale al momento della consegna.", "Prüfe die vereinbarte Portion und scanne bei der Übergabe den persönlichen Abholcode."],
  "routes.scan_collection_qr_hand_over": ["Abhol-QR scannen & übergeben", "Scan collection QR & hand over", "Teslim QR kodunu tara ve teslim et", "امسح QR الاستلام وسلّم", "Skeniraj QR preuzimanja i predaj", "Scansiona QR di ritiro e consegna", "Abhol-QR scannen & übergeben"],
  "routes.show_your_personal_code_only_on_site_when_your_agreed_portion_is_": ["Zeige deinen persönlichen Code erst vor Ort, wenn deine vereinbarte Portion bereitliegt. Nur die anbietende Person kann damit abschließen.", "Show your personal code only on site when your agreed portion is ready. Only the provider can complete with it.", "Kişisel kodunu yalnızca yerinde, porsiyonun hazırken göster. Bu kodla yalnızca sunan kişi tamamlayabilir.", "اعرض رمزك الشخصي في الموقع فقط عندما تكون حصتك جاهزة. يمكن لمقدم الطعام وحده الإتمام به.", "Osobni kod pokaži tek na licu mjesta kada je porcija spremna. Samo davatelj može njime dovršiti.", "Mostra il codice personale solo sul posto quando la porzione è pronta. Solo chi offre può usarlo per concludere.", "Zeige deinen Code erst beim Abholen. Deine Portion muss schon bereit sein. Nur die Person mit dem Essen kann damit die Übergabe abschließen."],
  "routes.your_personal_collection_code": ["Dein persönlicher Abholcode", "Your personal collection code", "Kişisel teslim alma kodun", "رمز استلامك الشخصي", "Tvoj osobni kod preuzimanja", "Il tuo codice personale di ritiro", "Dein persönlicher Abholcode"],
  "routes.renew_collection_code": ["Abholcode erneuern", "Renew collection code", "Teslim alma kodunu yenile", "جدّد رمز الاستلام", "Obnovi kod preuzimanja", "Rinnova codice di ritiro", "Abholcode erneuern"],
  "routes.my_portion_is_ready_show_code": ["Meine Portion ist bereit · Abholcode zeigen", "My portion is ready · Show code", "Porsiyonum hazır · Kodu göster", "حصتي جاهزة · اعرض الرمز", "Moja porcija je spremna · Pokaži kod", "La mia porzione è pronta · Mostra codice", "Meine Portion ist bereit · Abholcode zeigen"],
  "routes.receipt_is_confirmed_have_you_handed_over_the_agreed_portion": ["Der Empfang ist bestätigt. Hast du die vereinbarte Portion übergeben?", "Receipt is confirmed. Have you handed over the agreed portion?", "Teslim alma doğrulandı. Kararlaştırılan porsiyonu teslim ettin mi?", "تم تأكيد الاستلام. هل سلّمت الحصة المتفق عليها؟", "Primitak je potvrđen. Jesi li predao/la dogovorenu porciju?", "La ricezione è confermata. Hai consegnato la porzione concordata?", "Der Empfang ist bestätigt. Hast du die vereinbarte Portion übergeben?"],
  "routes.yes_complete_handoff": ["Ja, Übergabe abschließen", "Yes, complete handoff", "Evet, teslimi tamamla", "نعم، أكمل التسليم", "Da, dovrši primopredaju", "Sì, completa consegna", "Ja, Übergabe abschließen"],
  "routes.your_receipt_is_confirmed_the_provider_now_confirms_the_handoff_p": ["Dein Empfang ist bestätigt. Die anbietende Person bestätigt jetzt die Übergabe. Bis dahin bleiben Punkte ausstehend.", "Your receipt is confirmed. The provider now confirms the handoff. Points remain pending until then.", "Teslim alman doğrulandı. Sunan kişi şimdi teslimi onaylar. O zamana kadar puanlar bekler.", "استلامك مؤكد. يؤكد مقدم الطعام التسليم الآن. تبقى النقاط معلقة حتى ذلك الحين.", "Tvoj primitak je potvrđen. Davatelj sada potvrđuje primopredaju. Bodovi do tada ostaju na čekanju.", "La ricezione è confermata. Chi offre conferma ora la consegna. I punti restano in attesa fino ad allora.", "Du hast bestätigt, dass du das Essen hast. Jetzt muss die andere Person bestätigen. Erst dann bekommst du Punkte."],
